import{_ as t,o as i,c as n,a4 as r}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0024 — Rebranding en Teuthis-CMS et publication PyPI par Trusted Publishing","description":"Extrait de docs/adr/0024-rebranding-teuthis-cms-et-publication-pypi.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0024 — Rebranding en Teuthis-CMS et publication PyPI par Trusted Publishing","description":"Extrait de docs/adr/0024-rebranding-teuthis-cms-et-publication-pypi.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0024-rebranding-teuthis-cms-et-publication-pypi.md","filePath":"developpeurs/adr/0024-rebranding-teuthis-cms-et-publication-pypi.md"}'),a={name:"developpeurs/adr/0024-rebranding-teuthis-cms-et-publication-pypi.md"};function s(o,e,u,c,d,l){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0024--rebranding-en-teuthis-cms-et-publication-pypi-par-trusted-publishing" tabindex="-1">ADR-0024 — Rebranding en Teuthis-CMS et publication PyPI par Trusted Publishing <a class="header-anchor" href="#adr-0024--rebranding-en-teuthis-cms-et-publication-pypi-par-trusted-publishing" aria-label="Permalink to &quot;ADR-0024 — Rebranding en Teuthis-CMS et publication PyPI par Trusted Publishing {#adr-0024--rebranding-en-teuthis-cms-et-publication-pypi-par-trusted-publishing}&quot;">​</a></h1><p><strong>Date :</strong> 29 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> décision de diffusion publique, actée le 29 août 2026, en préparation de la publication PyPI ouverte par l&#39;ADR-0023</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0023 avait explicitement laissé ouverte, dans ses actions liées, la question de « la publication effective sur PyPI — hors périmètre technique de cette ADR — dépend d&#39;une décision de diffusion, pas encore prise ». Cette décision est prise : le Core est publié sur PyPI.</p><p>Deux questions se posent en même temps, et elles sont liées : sous quel nom, et par quel mécanisme.</p><p><strong>Le nom.</strong> Le produit s&#39;est appelé « calamars-CMS » tout au long de sa construction (15 epics, 24 ADR). Sébastien Rapuzzi a choisi de le rebrander en <strong>Teuthis-CMS</strong> avant la première publication publique — le nom <code>calamars-cms</code> était de toute façon disponible sur PyPI (vérifié, aucun paquet existant), mais le choix de renommer n&#39;est pas motivé par une indisponibilité, c&#39;est une décision de diffusion antérieure à toute publication, donc sans coût de migration pour un utilisateur existant.</p><p><strong>Le mécanisme.</strong> Publier sur PyPI suppose une authentification. La méthode historique — un jeton API généré sur pypi.org, stocké comme secret de dépôt GitHub, utilisé par <code>twine upload</code> — fonctionne, mais c&#39;est un secret de plus à générer, faire tourner et protéger d&#39;une fuite. PyPI propose depuis plusieurs années le <strong>Trusted Publishing</strong> : un mécanisme OIDC où PyPI fait confiance à un workflow GitHub Actions précisément identifié (dépôt, propriétaire, nom de fichier de workflow, environnement), sans qu&#39;aucun secret ne soit jamais généré ni stocké.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><h3 id="1-périmètre-du-renommage--la-marque-et-ce-qui-la-porte-pas-linfrastructure-qui-la-contient" tabindex="-1">1. Périmètre du renommage : la marque et ce qui la porte, pas l&#39;infrastructure qui la contient <a class="header-anchor" href="#1-périmètre-du-renommage--la-marque-et-ce-qui-la-porte-pas-linfrastructure-qui-la-contient" aria-label="Permalink to &quot;1. Périmètre du renommage : la marque et ce qui la porte, pas l&#39;infrastructure qui la contient {#1-périmètre-du-renommage--la-marque-et-ce-qui-la-porte-pas-linfrastructure-qui-la-contient}&quot;">​</a></h3><p>« calamars-CMS » devient <strong>« Teuthis-CMS »</strong> dans toute la prose du dépôt (docstrings, commentaires, ADRs, README, documentation), dans le nom de la distribution PyPI (<code>calamars-cms</code> → <code>teuthis-cms</code>), dans la commande CLI (<code>calamarscms</code> → <code>teuthiscms</code>, cf. ADR-0023), et dans les valeurs par défaut qui portent la marque par cohérence (identifiants de développement, nom de cookie de session, clés d&#39;état internes de l&#39;admin, textes affichés à l&#39;écran) — aucun déploiement réel n&#39;existe encore à ce jour, donc aucun coût de migration à ces changements.</p><p><strong>Trois choses ne changent pas, délibérément :</strong></p><ul><li><strong>Le dépôt GitHub reste nommé <code>calamars</code>.</strong> Le renommer casserait les liens, forks et clones existants pour un bénéfice purement cosmétique ; le nom d&#39;un dépôt n&#39;est pas le nom du produit qu&#39;il contient, de la même manière qu&#39;un dépôt appelé <code>linux</code> ne serait pas la marque déposée d&#39;une distribution.</li><li><strong>Le module Python interne reste <code>app</code>.</strong> L&#39;ADR-0023 l&#39;avait déjà tranché pour une tout autre raison (éviter un chantier mécanique sur une centaine de fichiers d&#39;import pour un nom générique) ; le rebranding ne rouvre pas cette décision, qui ne relève pas de la marque mais de la structure du code.</li><li><strong>La référence externe <code>CDC_CMS_AI_Native_v1.1</code> reste telle quelle.</strong> C&#39;est le nom d&#39;un document de spécification produit par ailleurs, pas le nom du produit livré ici — le confondre reviendrait à renommer une citation.</li></ul><h3 id="2-publication-par-trusted-publishing-oidc-aucun-jeton-en-secret-de-dépôt" tabindex="-1">2. Publication par Trusted Publishing (OIDC), aucun jeton en secret de dépôt <a class="header-anchor" href="#2-publication-par-trusted-publishing-oidc-aucun-jeton-en-secret-de-dépôt" aria-label="Permalink to &quot;2. Publication par Trusted Publishing (OIDC), aucun jeton en secret de dépôt {#2-publication-par-trusted-publishing-oidc-aucun-jeton-en-secret-de-dépôt}&quot;">​</a></h3><p>Le dépôt embarque un unique fichier <code>.github/workflows/workflow.yml</code> (nom imposé par la configuration du « pending publisher » sur PyPI — un nom de fichier différent romprait la vérification OIDC) portant deux publications distinctes :</p><ul><li>déclenchée manuellement (<code>workflow_dispatch</code>), vers <strong>TestPyPI</strong>, pour l&#39;essai avant toute publication réelle ;</li><li>déclenchée par la publication d&#39;une <em>Release</em> GitHub (<code>release: published</code>) — un geste humain délibéré, jamais un simple push — vers <strong>PyPI</strong>.</li></ul><p>Chacune s&#39;exécute sous un environnement GitHub dédié (<code>testpypi</code>, <code>pypi</code>), condition posée par PyPI elle-même pour le Trusted Publishing et occasion, au passage, de restreindre qui peut déclencher une publication réelle indépendamment de qui peut pousser du code sur <code>main</code>.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Jeton API PyPI classique, stocké en secret GitHub</strong></td><td>Écartée : un secret de plus à générer, faire tourner en cas de rotation et protéger d&#39;une fuite dans les journaux d&#39;exécution ou une mauvaise configuration de workflow — exactement la catégorie de risque que le Trusted Publishing supprime structurellement.</td></tr><tr><td><strong>Renommer aussi le dépôt GitHub en <code>teuthis</code></strong></td><td>Écartée : casserait les URL existantes pour un gain cosmétique ; le formulaire de Trusted Publishing que Sébastien Rapuzzi a lui-même rempli désigne explicitement <code>calamars</code> comme nom de dépôt.</td></tr><tr><td><strong>Renommer aussi le module Python <code>app</code></strong></td><td>Écartée, reconfirmée : ~100 fichiers d&#39;import à toucher pour un bénéfice sans rapport avec la question posée par cette ADR (la marque publique, pas la structure interne du code) — cf. ADR-0023.</td></tr><tr><td><strong>Publier directement sur PyPI sans passage par TestPyPI</strong></td><td>Écartée : une publication PyPI réelle est irréversible sous un même numéro de version (impossible de ré-uploader après suppression) ; TestPyPI est le filet de sécurité standard avant un geste qu&#39;on ne peut pas défaire.</td></tr><tr><td><strong>Déclencher la publication PyPI sur un tag Git plutôt que sur une Release GitHub</strong></td><td>Écartée : une Release GitHub est un geste explicite et visible (titre, notes, bouton « Publish »), qui laisse une trace humaine de l&#39;intention de publier — un tag peut être poussé par erreur ou par automatisation sans qu&#39;un humain n&#39;ait relu quoi que ce soit.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Aucun secret PyPI n&#39;existe nulle part dans la configuration du dépôt — rien à faire fuiter, rien à faire tourner.</li><li>Le renommage intervient avant toute publication réelle : zéro utilisateur existant à qui expliquer un changement de nom de paquet.</li><li>La publication réelle reste un geste humain explicite (créer une Release), distinct du travail de développement courant sur <code>main</code>.</li></ul><p><strong>Négatives</strong></p><ul><li>Le renommage touche ~150 occurrences mécaniques à travers le dépôt (prose, valeurs par défaut, textes d&#39;interface) — un chantier de portée large bien que mécanique, avec un risque de désynchronisation si un fichier est oublié (en particulier les tests qui vérifient une valeur par défaut ou un nom de conteneur en dur).</li><li>Deux « pending publishers » doivent être enregistrés côté compte (pypi.org et test.pypi.org), et le champ « propriétaire » de chacun doit correspondre exactement au propriétaire réel du dépôt GitHub au moment de la publication — une divergence fait échouer la vérification OIDC sans ambiguïté, mais seulement au moment de publier.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Confirmer le propriétaire réel du dépôt GitHub (<code>Bastien-OC20</code> ou une organisation <code>Les mogwais</code> à créer/transférer) avant de remplir les deux formulaires de Trusted Publisher — un désaccord entre ce champ et la réalité du dépôt fait échouer la publication. → <strong>Fait</strong> le 29/08/2026 : <code>Bastien-OC20</code>, pas d&#39;organisation créée ; c&#39;est ce propriétaire que déclarent les éditeurs de confiance PyPI et TestPyPI.</li><li>[x] Créer les environnements GitHub <code>pypi</code> et <code>testpypi</code> dans les réglages du dépôt. → <strong>Fait</strong> le 29/08/2026. Sans relecteur obligatoire : GitHub réserve cette protection aux dépôts publics ou aux plans payants ; le garde-fou restant est la création d&#39;une Release, réservée au propriétaire.</li><li>[x] Essai complet sur TestPyPI avant toute publication réelle sur PyPI. → <strong>Fait</strong> le 29/08/2026 : la configuration TestPyPI a été exercée et corrigée (<code>invalid-publisher</code>, nom de projet) le jour de la publication. L&#39;ordre exact des deux essais n&#39;a pas été consigné.</li></ul>',25)])])}const b=t(a,[["render",s]]);export{m as __pageData,b as default};
